\relax{cor_cellule_adjacente}
L'ensemble des germes des cellules adjacentes \`a la cellule
$\mathcal{V}(\operatorname{id})$ est constitu\'e de toutes :
\begin{enumerate}
\item[$\bullet$] les applications de caract\'eristique Jonqui\`eres,
\item[$\bullet$] les applications qui poss\`edent au plus $8$ points-base en position presque g\'en\'erale.
\end{enumerate}

\relax{cor_cellules_quasi_adjacentes}
L'ensemble des germes des cellules quasi-adjacentes \`a la cellule
$\mathcal{V}(\operatorname{id})$ est constitu\'e de toutes :
\begin{enumerate}
\item[$\bullet$] les applications de caract\'eristique Jonqui\`eres,
\item[$\bullet$] les applications qui poss\`edent au plus $9$ points-base en position presque g\'en\'erale.
\end{enumerate}

\relax{rmq_adjacent_sousgraphe_quasi}
{\rm Comme deux cellules qui ont une intersection non vide
poss\`edent \'egalement une classe commune \`a l'infini
(\cite[Corollaire 5.6]{Lovoronoi1}), le graphe de quasi-adjacence
est en fait obtenu en ajoutant des ar\^etes au graphe d'adjacence.}

\relax{proprietes_c} {\rm        L'ensemble $\mathcal{E}$ est le
sous-espace de $\mathbb{H}^{\infty}$ constitu\'e des classes
\[c=n\ell-\sum\limits_{p\in\mathcal{B}(\mathbb{P}^2)}\lambda_pe_{p} \ \ \text{
(}n\text{ r\'eel}\geq 1\text{)}\] satisfaisant :
        \begin{enumerate}
            \item[\rm 1)] \phantomsection \relax{propriete_coeff_classe} $\lambda_p\geq 0$ pour tout $p\in \mathcal{B}(\mathbb{P}^2)$,
            \item[\rm 2)] \phantomsection \relax{propriete_classe_canonique} la \emph{positivit\'e contre la classe anti-canonique} : \[ 3n-\sum\limits_{p\in \mathcal{B}(\mathbb{P}^2)}\lambda_p\geq 0,\]
            \item[\rm 3)] \phantomsection \relax{propriete_classe_exces} la \emph{positivit\'e des exc\`es} de tout point $p\in\mathcal{B}(\mathbb{P}^2)$ : \[\lambda_{p} - \sum\limits_{\substack{q\in \mathcal{B}(\mathbb{P}^2)\\ q \to p }}\lambda_{q}\geq0,\]
            \item[\rm 4)] \phantomsection \relax{propriete_classe_bezout} la \emph{condition de B\'ezout} : pour toute courbe de $\mathbb{P}^2$ de degr\'e $d$ passant avec multiplicit\'e $\mu_p$ en chaque point $p\in\mathcal{B}(\mathbb{P}^2)$ : \[nd-\sum\limits_{p\in \mathcal{B}(\mathbb{P}^2)}\lambda_p\mu_p\geq0.\]
        \end{enumerate}}

\relax{thm_bow}
    Soient $h\geq 0$ et $\Gamma$ un graphe connexe muni de la distance standard. Supposons que pour tous $x$ et $y$ appartenant \`a l'ensemble des sommets $S(\Gamma)$, il existe un sous-graphe $\Gamma(x,y)$ de $\Gamma$ connexe par arcs v\'erifiant :
    \begin{enumerate}
        \item[1)] \phantomsection \relax{critere_bow1}  Pour tout $x$, $y\in S(\Gamma)$, $x$, $y\in\Gamma(x,y)$.
        \item[2)] \phantomsection \relax{critere_bow2} Pour tout $x$, $y$, $z\in S(\Gamma)$, $\Gamma(x,y)\subseteq \mathcal{N}_h(\Gamma(x,z)\cup\Gamma(y,z))$ o\`u $\mathcal{N}_h$ signifie le $h$-voisinage tubulaire.
        \item[3)] \phantomsection \relax{critere_bow3} Pour tout $x$, $y\in S(\Gamma)$ tels que $\operatorname{d}(x,y)\leq 1$, le diam\`etre de $\Gamma(x,y)$ dans $\Gamma$ est au plus $h$.
    \end{enumerate}
    Alors $\Gamma$ est $\delta$-hyperbolique avec $\delta$ d\'ependant de $h$.

\relax{rmq_longueur}
{\rm    La distance entre deux sommets $\bar{f}$ et $\bar{g}$ est
donn\'ee par la longueur de l'application $f^{-1}\circ g$ introduit
par J. Blanc et J-P. Furter dans \cite{BlF}.}

\relax{prop_formule_action_halphen}
        \`A chaque \'el\'ement de $a\in\operatorname{K}_X^{\perp}/\langle\operatorname{K}_X\rangle$ est associ\'e un automorphisme de $X$, et donc une isom\'etrie $\tau_a$ de $\operatorname{Pic}(X)$ via la formule :
        \[\begin{array}{cccc}
        \tau_a : &\operatorname{Pic}(X) &\rightarrow &\operatorname{Pic}(X)\\
        &d&\mapsto & d-(\operatorname{K}_X\cdot\ d)a+(a\cdot d-\frac{1}{2}(\operatorname{K}_X\cdot\   d)(a\cdot a))\operatorname{K}_X
        \end{array}. \]

\relax{lemme_deg_fonction_longueur}
    Soit $h\in\operatorname{Bir}(\mathbb{P}^2)$ telle que $h$ poss\`ede au plus $9$ points-base. Nous avons alors :
    \[\deg(h)\leq 5\operatorname{\ell g}(h)^2.\]

\relax{thm_qi_gc_z2}
   Le graphe de Wright modifi\'e poss\`ede un sous-graphe quasi-isom\'etrique au graphe de Cayley de $\mathbb{Z}^2$, not\'e $\mathcal{GC}(\mathbb{Z}^2)$. Plus pr\'ecis\'ement,
   en consid\'erant les applications $g_1,g_2\in\operatorname{Bir}(\mathbb{P}^2)$ construites pr\'ec\'edemment, l'inclusion :
    \[\begin{array}{cccc}
        \mathcal{I}:& \mathcal{GC}(<g_1,g_2>)&\rightarrow& \mathcal{G} \\
        & f &\mapsto &\overline{f}
        \end{array}\] est une quasi-isom\'etrie sur son image.

\relax{prop_qi_graphes}
        L'application  \[\begin{array}{cccc}
                                \mathcal{I} :& \mathcal{S}(\mathcal{A})&\rightarrow& \mathcal{S}(\mathcal{G})\\
                                & f_{{\scriptscriptstyle{\#}}}(\ell) &\mapsto &\bar{f}
                                \end{array}\] entre les sommets du graphe d'adjacence $\mathcal{S}(\mathcal{A})$ et les sommets du graphe de Wright modifi\'e $\mathcal{S}(\mathcal{G})$ est une quasi-isom\'etrie. En particulier, le graphe de Wright $\mathcal{W}$, le graphe de Wright modifi\'e $\mathcal{G}$ et le graphe d'adjacence $\mathcal{A}$ sont quasi-isom\'etriques.

\relax{lemme_classe_speciale_mult}
        Soit $c=n\ell-\sum_{p\in\mathcal{B}(\mathbb{P}^2)}\lambda_pe_{p}\in \mathcal{V}(\operatorname{id})$ une classe sp\'eciale. Soient deux points $r$ et $q$ distincts de $p_0$ v\'erifiant $\lambda_r \leq \lambda_q$. Si $p_0$, $q$ et $r$ sont align\'es ou le support d'une application quadratique, alors :
        \[\lambda_r < \frac{n}{4}.\]

{\rm S'il existe un point-base $p$ de $f_2^{-1}$ tel que $
\lambda_p\leq\frac{5n}{16}$ alors $c_1\cdot {f_2}_{{\scriptscriptstyle{\#}}}(\ell)\geq
\frac{49}{48}n$.}

\relax{fait_pt_min_f_2}
{\rm    Il existe un point-base de $f_2^{-1}$,  $p\in\operatorname{Bs}(f_2^{-1})$,
tel que pour tout point-base $q\in\operatorname{Bs}(f_1^{-1})$, les
multiplicit\'es associ\'ees satisfont : $\lambda_p\leq \lambda_q$. }

{\rm Si $\lambda_{p_0}< \frac{3n}{8}$ et si nous sommes dans le cas
\hyperref[enum_card]{a)} alors il existe un point-base $p$ de
$f_2^{-1}$ tel que $ \lambda_p\leq\frac{5n}{16}$.}

{\rm Si $\lambda_{p_0}< \frac{3n}{8}$ et si nous sommes dans le cas
\hyperref[enum_align]{b)} alors il existe un point-base $p$ de
$f_2^{-1}$ tel que $ \lambda_p\leq\frac{5n}{16}$.}

{\rm Si $\lambda_{p_0}< \frac{3n}{8}$ et si nous sommes dans le cas
\hyperref[enum_conique]{c)} alors il existe un point-base $p$ de
$f_2^{-1}$ tel que $ \lambda_p\leq\frac{5n}{16}$.}

{\rm Si $\lambda_{p_0}< \frac{3n}{8}$ et si nous sommes dans le cas
\hyperref[enum_adherents]{d)} alors il existe un point-base $p$ de
$f_2^{-1}$ tel que $ \lambda_p\leq\frac{5n}{16}$.}

Par la d\'efinition des cellules de Vorono\"{\i}, nous avons d'une part \[\operatorname{d}(c_1,\ell)\leq\operatorname{d}(c_1,{f_2}_{{\scriptscriptstyle{\#}}}(\ell)) \text{ et }  \operatorname{d}(c_2,{f_2}_{{\scriptscriptstyle{\#}}}(\ell))\leq\operatorname{d}(c_2,\ell)\] et d'autre part, par l'in\'egalit\'e triangulaire nous obtenons :
        \begin{equation}\relax{dist_c1_f_2}
        \operatorname{d}(c_1,{f_2}_{{\scriptscriptstyle{\#}}}(\ell)) \leq \varepsilon+ \operatorname{d}(c_2,{f_2}_{{\scriptscriptstyle{\#}}}(\ell))\leq \varepsilon+\operatorname{d}(c_2,\ell)\leq 2\varepsilon +\operatorname{d}(c_1,\ell).
        \end{equation}

         Par cons\'equent nous avons l'encadrement suivant :
         \begin{equation*}
        0\leq \operatorname{d}(c_1,{f_2}_{{\scriptscriptstyle{\#}}}(\ell))-\operatorname{d}(c_1,\ell)\leq 2\varepsilon.
         \end{equation*}

        En utilisant la majoration pr\'ec\'edente et par concavit\'e de la fonction $\operatorname{argcosh}$ nous obtenons l'in\'egalit\'e annonc\'ee :
        \begin{align*}
        2\varepsilon \geq \operatorname{d}(c_1,{f_2}_{{\scriptscriptstyle{\#}}}(\ell))-\operatorname{d}(c_1,\ell)&=\operatorname{argcosh}(c_1\cdot{f_2}_{{\scriptscriptstyle{\#}}}(\ell))-\operatorname{argcosh}(c_1\cdot\ell)\\
        &\geq \frac{c_1\cdot{f_2}_{{\scriptscriptstyle{\#}}}(\ell)-c_1\cdot\ell}{\sqrt{(c_1\cdot{f_2}_{{\scriptscriptstyle{\#}}}(\ell))^2-1}}\\
        &\geq \frac{c_1\cdot{f_2}_{{\scriptscriptstyle{\#}}}(\ell)-c_1\cdot\ell}{c_1\cdot{f_2}_{{\scriptscriptstyle{\#}}}(\ell)}= 1-\frac{c_1\cdot\ell}{c_1\cdot{f_2}_{{\scriptscriptstyle{\#}}}(\ell)}.
        \end{align*}

\vspace{-0.9cm}

\relax{lemme_distance_cellules_disjointes}
    Il existe $M>0$ tel que pour toutes applications $f_1,f_2\in\operatorname{Bir}(\mathbb{P}^2)$ telles que $\operatorname{d}_{\bar{\mathcal{A}}}({f_1}_{{\scriptscriptstyle{\#}}}(\ell),{f_2}_{{\scriptscriptstyle{\#}}}(\ell))= 2$, nous avons :
    \[\operatorname{d}(\mathcal{V}(f_1),\mathcal{V}(f_2))\geq M.\]
